import 'dart:async';import 'package:flutter/material.dart';import 'package:sehatak/core/services/sleep/sleep_service.dart';import 'package:sehatak/presentation/widgets/futuristic/glass_card.dart';import 'package:sehatak/presentation/widgets/futuristic/futuristic_background.dart';import 'package:sehatak/presentation/widgets/futuristic/futuristic_app_bar.dart';import 'package:sehatak/presentation/widgets/futuristic/holographic_number.dart';import 'package:sehatak/presentation/widgets/futuristic/futuristic_bar_chart.dart';import 'package:sehatak/presentation/widgets/futuristic/futuristic_stat_card.dart';
class SleepTrackerScreen extends StatefulWidget{const SleepTrackerScreen({super.key});@override State<SleepTrackerScreen> createState()=>_S();}class _S extends State<SleepTrackerScreen>{final s=SleepService.instance;StreamSubscription<SleepSnapshot>? sub;int sec=0;bool active=false;List<double> days=[];@override void initState(){super.initState();sub=s.updates.listen((x){if(mounted)setState((){active=x.isTracking;sec=x.elapsedSeconds;});});_load();}Future<void>_load()async{await s.restoreTracking();final r=await s.getWeeklySleepRecords();if(mounted)setState(()=>days=r.map((e)=>e.durationMinutes/60).toList().reversed.toList());}Future<void>_toggle()async{if(active){await s.stopSleepTracking();}else{await s.startSleepTracking();}}@override void dispose(){sub?.cancel();super.dispose();}@override Widget build(BuildContext c){final h=sec~/3600,m=(sec%3600)~/60;return Scaffold(backgroundColor:const Color(0xFF0A0E1A),appBar:const FuturisticAppBar(title:'تتبع النوم'),body:FuturisticBackground(glowColor:const Color(0xFF7B61FF),child:ListView(padding:const EdgeInsets.all(16),children:[GlassCard(glowColor:const Color(0xFF7B61FF),child:Column(children:[const Icon(Icons.nightlight_round,color:Color(0xFF7B61FF),size:54),const SizedBox(height:10),HolographicNumber(value:active?h.toString():'--',unit:active?('ساعة و '+m.toString()+' دقيقة'):'متوسط آخر 7 أيام',color:const Color(0xFF7B61FF),fontSize:64),const SizedBox(height:16),FilledButton.icon(onPressed:_toggle,icon:Icon(active?Icons.stop:Icons.bedtime),label:Text(active?'إنهاء جلسة النوم':'بدء جلسة النوم'))])),const SizedBox(height:12),GlassCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('مدة النوم اليومية',style:TextStyle(color:Colors.white,fontWeight:FontWeight.w800)),const SizedBox(height:8),days.length>1?FuturisticBarChart(values:days,color:const Color(0xFF7B61FF)):const SizedBox(height:130,child:Center(child:Text('أضف جلسة نوم لعرض الرسم',style:TextStyle(color:Colors.white54))))])),const SizedBox(height:12),Row(children:[FuturisticStatCard(icon:Icons.bedtime,label:'الحالة',value:active?'جاري التتبع':'متوقف',color:const Color(0xFF7B61FF)),const SizedBox(width:8),FuturisticStatCard(icon:Icons.auto_graph,label:'الجلسات',value:days.length.toString(),color:const Color(0xFF00E5A0))])])));}